#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator Server
 * For testing the deploy.sh script's POST to /api/deploy-config
 */

const http = require('http');
const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/deploy-config') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const config = JSON.parse(body);

        console.log('\n=== Received Deploy Config ===');
        console.log('Timestamp:', config.timestamp);
        console.log('Project:', config.project);
        console.log('\nEnvironment Variables:');

        for (const [key, value] of Object.entries(config.environment_variables)) {
          // Mask sensitive values for display
          const displayValue = value.length > 20 
            ? value.substring(0, 10) + '...' + value.substring(value.length - 5)
            : value;
          console.log(`  ${key}: ${displayValue}`);
        }

        console.log('\n=== Config Logged for Audit ===\n');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'success',
          message: 'Configuration received and logged for audit compliance',
          config_id: `CFG-${Date.now()}`
        }));

      } catch (error) {
        console.error('Error parsing config:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: 'Invalid JSON payload'
        }));
      }
    });

  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Not found'
    }));
  }
});

server.listen(PORT, () => {
  console.log(`\n🚀 Mock Deployment Orchestrator running on port ${PORT}`);
  console.log(`   Endpoint: http://localhost:${PORT}/api/deploy-config`);
  console.log(`   Waiting for deploy configs...\n`);
});

