#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator API Server
 * For testing the deploy.sh script
 */

const http = require('http');
const PORT = 47301;

const server = http.createServer((req, res) => {
  console.log(`\n${new Date().toISOString()} - ${req.method} ${req.url}`);
  console.log('Headers:', JSON.stringify(req.headers, null, 2));

  if (req.method === 'POST' && req.url === '/api/deploy-config') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('\n📦 Received Deployment Config:');
        console.log('================================');
        console.log(JSON.stringify(data, null, 2));
        console.log('================================\n');

        // Validate required fields
        if (!data.timestamp || !data.project || !data.config) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            error: 'Missing required fields',
            required: ['timestamp', 'project', 'config']
          }));
          return;
        }

        // Success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'success',
          message: 'Deployment config received and logged for audit compliance',
          audit_id: `AUDIT-${Date.now()}`,
          config_keys: Object.keys(data.config),
          received_at: new Date().toISOString()
        }));

      } catch (error) {
        console.error('Error parsing JSON:', error);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          error: 'Invalid JSON',
          message: error.message
        }));
      }
    });

  } else {
    // Handle unknown routes
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      error: 'Not found',
      message: 'Unknown endpoint'
    }));
  }
});

server.listen(PORT, () => {
  console.log(`\n🚀 Mock Deployment Orchestrator running on http://localhost:${PORT}`);
  console.log(`📍 Endpoint: POST /api/deploy-config`);
  console.log('⏳ Waiting for deployment configs...\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\n👋 Shutting down server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

