#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator Server
 * For testing the deploy.sh script
 * Listens on http://localhost:47301/api/deploy-config
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;
const AUDIT_LOG = path.join(__dirname, 'deployment-audit.log');

const server = http.createServer((req, res) => {
    // Set CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    // Handle preflight
    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    // Only accept POST to /api/deploy-config
    if (req.method !== 'POST' || req.url !== '/api/deploy-config') {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            error: 'Not Found',
            message: 'Expected POST /api/deploy-config'
        }));
        return;
    }

    let body = '';

    req.on('data', chunk => {
        body += chunk.toString();
    });

    req.on('end', () => {
        try {
            const data = JSON.parse(body);

            console.log('\n' + '='.repeat(60));
            console.log('📦 DEPLOYMENT CONFIG RECEIVED');
            console.log('='.repeat(60));
            console.log(`Timestamp: ${data.timestamp}`);
            console.log(`Project: ${data.project}`);
            console.log('\nConfiguration Variables:');
            console.log('-'.repeat(60));

            const configKeys = Object.keys(data.config || {});
            if (configKeys.length === 0) {
                console.log('⚠️  No configuration variables received');
            } else {
                configKeys.forEach(key => {
                    const value = data.config[key];
                    // Mask sensitive values in console
                    const displayValue = value.length > 20 
                        ? value.substring(0, 10) + '...' + value.substring(value.length - 7)
                        : value.substring(0, 5) + '***';
                    console.log(`  ✓ ${key}: ${displayValue}`);
                });
            }

            console.log('-'.repeat(60));
            console.log(`Total variables: ${configKeys.length}`);
            console.log('='.repeat(60) + '\n');

            // Log to audit file
            const auditEntry = {
                receivedAt: new Date().toISOString(),
                ...data
            };

            const logLine = JSON.stringify(auditEntry) + '\n';
            fs.appendFileSync(AUDIT_LOG, logLine);
            console.log(`✓ Audit log written to: ${AUDIT_LOG}`);

            // Send success response
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                success: true,
                message: 'Configuration received and logged for audit compliance',
                audit_id: `AUDIT-${Date.now()}`,
                variables_count: configKeys.length
            }));

        } catch (error) {
            console.error('✗ Error parsing request:', error.message);
            res.writeHead(400, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                error: 'Bad Request',
                message: 'Invalid JSON payload'
            }));
        }
    });

    req.on('error', (error) => {
        console.error('✗ Request error:', error.message);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            error: 'Internal Server Error',
            message: error.message
        }));
    });
});

server.listen(PORT, 'localhost', () => {
    console.log('\n' + '='.repeat(60));
    console.log('🚀 Mock Deployment Orchestrator Running');
    console.log('='.repeat(60));
    console.log(`Listening on: http://localhost:${PORT}`);
    console.log(`Endpoint: POST /api/deploy-config`);
    console.log(`Audit Log: ${AUDIT_LOG}`);
    console.log('='.repeat(60));
    console.log('\nWaiting for deployment configurations...\n');
});

server.on('error', (error) => {
    if (error.code === 'EADDRINUSE') {
        console.error(`✗ Error: Port ${PORT} is already in use`);
        console.error('Please stop the existing server or choose a different port');
    } else {
        console.error('✗ Server error:', error.message);
    }
    process.exit(1);
});
